"""Controlled BP diagnostics on fixed validation IDs; no new tuning or timing claims."""
import sys,pathlib,json
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parents[1]/'python'))
from common import *
from freeze_guard import verify_lock
from _accuracy_native import LocalSolver
pin();verify_lock();dest=ROOT/'results/BP_quality_audit.jsonl';assert not dest.exists();manifest=json.loads((ROOT/'results/new_samples/manifest.json').read_text());base=json.loads((ROOT/'configs/P2_validation.json').read_text())['configs'];controls=json.loads((ROOT/'configs/P2_control_amendment.json').read_text())['configs'];summary=[]
for work in WORKS:
 a=model(work);w=np.log((1-a['p'])/a['p']);sp=manifest['workloads'][work]['splits']['validation'];z=np.load(ROOT/sp['path']);ss=z['detectors'][:32];obs=z['observables'][:32];profiles=[c for c in base[work] if c['name'] in ['bp_reference','bp_norm08','bp_norm10','bp_damp08','bp_serial','bp_norm05']]+controls[work]
 for cfg in profiles:
  solver=LocalSolver(a['d'].shape[0],supports(a['d']),a['p'].tolist(),w.tolist(),'bphuf',cfg.get('iterations',30),0);solver.configure_bp(cfg.get('scale',.625),cfg.get('damping',0),cfg.get('schedule','parallel')=='serial');rows=[]
  for i,s in enumerate(ss):
   q=solver.solve(s);x=np.asarray(q['correction'],dtype=np.uint8);assert valid(a,x,s);llr=np.asarray(q['llr']);finite=llr[np.isfinite(llr)];r=dict(workload=work,profile=cfg['name'],config=cfg,validation_id=sp['sample_id_prefix']+':'+str(i),zero_bypass=bool(q['zero_bypass']),bp_converged=bool(q['bp_converged']),iterations=q['counts']['bp_iterations'],hard_residual_weight=0 if q['zero_bypass'] else q['bp_hard_residual_weight'],nan_llrs=int(np.isnan(llr).sum()),infinite_llrs=int(np.isinf(llr).sum()),finite_llr_quantiles=np.quantile(finite,[.1,.5,.9],method='nearest').tolist() if len(finite) else None,after_HUF_logical_failure=bool(np.any(frame(a,x)!=obs[i])),scope='same full D/prior/syndrome; joint BP+HUF diagnostic, not outer-policy accuracy or publication timing');rows.append(r)
   with dest.open('a') as out:out.write(json.dumps(r)+'\n')
  summary.append(dict(workload=work,profile=cfg['name'],n=len(rows),converged=sum(r['bp_converged'] for r in rows),mean_iterations=float(np.mean([r['iterations'] for r in rows])),mean_hard_residual=float(np.mean([r['hard_residual_weight'] for r in rows])),after_HUF_failures=sum(r['after_HUF_logical_failure'] for r in rows),nan_llrs=sum(r['nan_llrs'] for r in rows)))
atomic(ROOT/'results/BP_quality_summary.json',summary);lines=['# Controlled BP quality diagnostics','','All eight previously declared P2 presets use the same full detector graph, priors and first 32 validation syndromes per workload. Profiles were not selected or changed using this follow-up. Iterations, hard-decision residuals and convergence precede HUF; logical failures follow the joint BP+HUF solve. These small exploratory global-graph diagnostics are not measurements of the complete partition/repair policy, not additional independent test shots, and not publication latency. No correlated fault or logical mapping changes.','','| Workload | Profile | Converged /32 | Mean iterations | Mean hard residual | Joint after-HUF failures /32 | NaN LLRs |','|---|---|---:|---:|---:|---:|---:|']
